package com.homelab.commandcentre.core

import com.homelab.commandcentre.core.api.ApiJson
import kotlinx.serialization.DeserializationStrategy

/** Loads JSON captured from the real backend (generated by running the FastAPI app). */
object Fixtures {
    fun text(name: String): String =
        checkNotNull(Fixtures::class.java.getResourceAsStream("/fixtures/$name.json")) { "missing fixture $name" }
            .bufferedReader().readText()

    fun <T> load(name: String, strategy: DeserializationStrategy<T>): T = ApiJson.decodeFromString(strategy, text(name))
}
